32	#[derive(Parser, Debug)]
33	#[command(
34	    name = "xtask",
35	    about = "开发辅助工具（本地门禁/覆盖率/脚本静态检查）",
36	    arg_required_else_help = true,
37	    after_help = r#"ALIASES (in .cargo/config.toml):
38	  cargo check-all          -> cargo run -p xtask -- check-all
39	  cargo cov                -> cargo run -p xtask -- cov
40	  cargo script-check       -> cargo run -p xtask -- script-check
41	  cargo mutants-check      -> cargo run -p xtask -- mutants
42	  cargo release            -> cargo run -p xtask -- release
43	"#
44	)]
45	struct Cli {
46	    #[command(subcommand)]
47	    command: XtaskCommand,
48	}
49	
50	#[derive(Subcommand, Debug)]
51	enum XtaskCommand {
52	    /// 运行 fmt、clippy（自动 fix）、test
53	    CheckAll,
54	
55	    /// 运行 workspace 覆盖率报告（HTML；排除工具 crate 与平台胶水代码）
56	    Cov,
57	
58	    /// 检查脚本文件（语法、label、资源引用）
59	    ScriptCheck(ScriptCheckArgs),
60	
61	    /// 运行变异测试（vn-runtime），检测测试质量
62	    Mutants(MutantsArgs),
63	
64	    /// 一键发布：pack → copy assets.zip → dx bundle → cleanup
65	    Release,
66	}
