131	fn run(step: &str, sh: &Shell, program: &str, args: &[&str]) -> anyhow::Result<()> {
132	    eprintln!("\n==> {step}");
133	    sh.cmd(program)
134	        .args(args)
135	        .run()
136	        .with_context(|| format!("{step} failed"))?;
137	    Ok(())
138	}
139	
140	fn run_status(step: &str, program: &str, args: &[&str]) -> anyhow::Result<ExitStatus> {
141	    eprintln!("\n==> {step}");
142	    eprintln!("$ {program} {}", args.join(" "));
143	    std::process::Command::new(program)
144	        .args(args)
145	        .status()
146	        .with_context(|| format!("{step} failed to start"))
147	}
148	
149	/// 覆盖率排除规则
150	///
151	/// 排除不可单元测试的平台/框架胶水代码：
152	/// - `src/lib.rs`：模块声明与重导出
153	/// - `vn-runtime/src/error.rs`：thiserror derive，无手写逻辑
154	///
155	/// 从 `cov-ignore-regex.txt` 构建覆盖率忽略正则。
156	///
157	/// 文件每行一个模式；注释行（`#`）和空行会被跳过。
158	/// 运行时用 `|` 连接所有模式。
159	fn cov_ignore_regex() -> String {
160	    include_str!("../cov-ignore-regex.txt")
161	        .lines()
162	        .map(str::trim)
163	        .filter(|l| !l.is_empty() && !l.starts_with('#'))
164	        .collect::<Vec<_>>()
165	        .join("|")
166	}
167	
168	fn ensure_cargo_llvm_cov_available(sh: &Shell) -> anyhow::Result<()> {
169	    if sh
170	        .cmd("cargo")
171	        .args(["llvm-cov", "--version"])
172	        .run()
173	        .is_ok()
174	    {
175	        return Ok(());
176	    }
177	    anyhow::bail!(
178	        "cargo llvm-cov 不可用。\n\
179	请先安装：\n\
180	  - cargo install cargo-llvm-cov\n\
181	  - rustup component add llvm-tools-preview\n\
182	然后重试。"
183	    )
184	}
185	
186	fn main() -> ExitCode {
187	    if let Err(e) = real_main() {
188	        eprintln!("xtask error: {e:#}");
189	        return ExitCode::from(1);
190	    }
191	    ExitCode::from(0)
192	}
193	
194	fn real_main() -> anyhow::Result<()> {
195	    let cli = Cli::parse();
196	    let sh = Shell::new()?;
197	
198	    match cli.command {
199	        XtaskCommand::CheckAll => {
200	            let fmt_check = std::process::Command::new("cargo")
201	                .args(["fmt", "--all", "--", "--check"])
202	                .status()
203	                .context("cargo fmt --check failed to start")?;
204	            if !fmt_check.success() {
205	                eprintln!("\nfmt 检查发现差异，正在 apply...");
206	                run("cargo fmt --all", &sh, "cargo", &["fmt", "--all"])?;
207	            }
208	
209	            run(
210	                "cargo clippy --workspace --fix --allow-dirty",
211	                &sh,
212	                "cargo",
213	                &["clippy", "--workspace", "--fix", "--allow-dirty"],
214	            )?;
215	
216	            run(
217	                "cargo test --workspace --quiet",
218	                &sh,
219	                "cargo",
220	                &["test", "--workspace", "--quiet"],
221	            )?;
222	
223	            if !fmt_check.success() {
224	                anyhow::bail!("fmt check failed");
225	            }
226	        }
227	        XtaskCommand::Cov => {
228	            ensure_cargo_llvm_cov_available(&sh)?;
229	
230	            // Cranelift 不支持 -Cinstrument-coverage，覆盖率须使用 LLVM 后端
231	            let _llvm_guard = sh.push_env("CARGO_PROFILE_DEV_CODEGEN_BACKEND", "llvm");
232	
233	            let cov_ignore = cov_ignore_regex();
234	            run(
235	                "cargo llvm-cov --workspace (with exclusions)",
236	                &sh,
237	                "cargo",
238	                &[
239	                    "llvm-cov",
240	                    "--quiet",
241	                    "--workspace",
242	                    "--exclude",
243	                    "xtask",
244	                    "--exclude",
245	                    "asset-packer",
246	                    "--features",
247	                    "desktop",
248	                    "--html",
249	                    "--ignore-filename-regex",
250	                    &cov_ignore,
251	                ],
252	            )?;
253	
254	            eprintln!("\nCoverage HTML: target/llvm-cov/html/index.html");
255	        }
256	        XtaskCommand::ScriptCheck(args) => {
257	            script_check(args)?;
258	        }
259	        XtaskCommand::Mutants(args) => {
260	            run_mutants(&sh, args)?;
261	        }
262	        XtaskCommand::Release => {
263	            cmd_release(&sh)?;
264	        }
265	    }
266	
267	    Ok(())
268	}
