285	#[expect(
286	    clippy::items_after_statements,
287	    reason = "release step consts/structs are colocated with their usage"
288	)]
289	fn cmd_release(sh: &Shell) -> anyhow::Result<()> {
290	    ensure_dx_available(sh)?;
291	
292	    const HOST_DIOXUS: &str = "host-dioxus";
293	
294	    #[derive(Deserialize)]
295	    struct CargoManifest {
296	        package: CargoPackage,
297	    }
298	
299	    #[derive(Deserialize)]
300	    struct CargoPackage {
301	        name: String,
302	        version: String,
303	    }
304	
305	    let workspace_root = workspace_root()?;
306	
307	    // Step 1: 打包资源
308	    run(
309	        "cargo pack — 打包资源 ZIP",
310	        sh,
311	        "cargo",
312	        &[
313	            "run",
314	            "-p",
315	            "asset-packer",
316	            "--",
317	            "--input",
318	            "assets",
319	            "--output",
320	            "assets.zip",
321	        ],
322	    )?;
323	
324	    let assets_zip = workspace_root.join("assets.zip");
325	    if !assets_zip.exists() {
326	        anyhow::bail!("asset-packer 未产出 assets.zip");
327	    }
328	
329	    // Step 2: 复制到 host-dioxus/（dx 的 [bundle] resources 从此处读取）
330	    let target_zip = workspace_root.join(HOST_DIOXUS).join("assets.zip");
331	    std::fs::copy(&assets_zip, &target_zip).context("复制 assets.zip 到 host-dioxus/ 失败")?;
332	    eprintln!("  assets.zip → host-dioxus/assets.zip");
333	
334	    // Step 3: dx bundle
335	    let result = run_status(
336	        "dx bundle — 构建 NSIS 安装包",
337	        "dx",
338	        &[
339	            "bundle",
340	            "--release",
341	            "--package",
342	            HOST_DIOXUS,
343	            "--package-types",
344	            "nsis",
345	        ],
346	    );
347	
348	    // Step 4: 清理（无论成功失败）
349	    eprintln!("\n==> 清理临时文件");
350	    if let Err(e) = std::fs::remove_file(&target_zip) {
351	        eprintln!("  清理 host-dioxus/assets.zip 失败: {e} (请手动删除)");
352	    } else {
353	        eprintln!("  已删除 host-dioxus/assets.zip");
354	    }
355	    let _ = std::fs::remove_file(&assets_zip);
356	
357	    result?;
358	
359	    let cargo_toml_path = workspace_root.join(HOST_DIOXUS).join("Cargo.toml");
360	    let cargo_toml_content =
361	        std::fs::read_to_string(&cargo_toml_path).context("无法读取 host-dioxus/Cargo.toml")?;
362	    let manifest: CargoManifest =
363	        toml::from_str(&cargo_toml_content).context("无法解析 host-dioxus/Cargo.toml")?;
364	    let pascal_name = manifest.package.name.to_upper_camel_case();
365	    let exe_name = format!("{pascal_name}_{}_x64-setup.exe", manifest.package.version);
366	    let installer = workspace_root
367	        .join("target")
368	        .join("dx")
369	        .join(HOST_DIOXUS)
370	        .join("bundle")
371	        .join("windows")
372	        .join("nsis")
373	        .join(&exe_name);
374	
375	    if installer.exists() {
376	        eprintln!("\n  安装包: {}", installer.display());
377	    } else {
378	        anyhow::bail!("dx bundle 完成但未找到 {exe_name}");
379	    }
380	
381	    Ok(())
382	}
