384	fn workspace_root() -> anyhow::Result<PathBuf> {
385	    let mut dir = std::env::current_dir().context("无法获取当前目录")?;
386	    loop {
387	        let cargo_toml = dir.join("Cargo.toml");
388	        if cargo_toml.is_file() {
389	            let content = std::fs::read_to_string(&cargo_toml).context("无法读取 Cargo.toml")?;
390	            if content.contains("[workspace]") {
391	                return Ok(dir);
392	            }
393	        }
394	        if !dir.pop() {
395	            anyhow::bail!("未找到 workspace 根目录（无包含 [workspace] 的 Cargo.toml）");
396	        }
397	    }
398	}
399	
400	//=============================================================================
401	// mutants 命令实现
402	//=============================================================================
403	
404	#[derive(Debug, Default)]
405	struct MutantsReportSummary {
406	    caught: usize,
407	    missed: usize,
408	    timeout: usize,
409	    unviable: usize,
410	}
411	
412	fn ensure_cargo_mutants_available(sh: &Shell) -> anyhow::Result<()> {
413	    if sh.cmd("cargo").args(["mutants", "--version"]).run().is_ok() {
414	        return Ok(());
415	    }
416	    anyhow::bail!(
417	        "cargo-mutants 不可用。\n\
418	         请先安装：cargo install cargo-mutants\n\
419	         然后重试。"
420	    )
421	}
422	
423	fn mutants_output_dir(extra: &[String]) -> PathBuf {
424	    let mut iter = extra.iter();
425	    while let Some(arg) = iter.next() {
426	        if arg == "--output" {
427	            if let Some(path) = iter.next() {
428	                return PathBuf::from(path);
429	            }
430	            break;
431	        }
432	
433	        if let Some(path) = arg.strip_prefix("--output=") {
434	            return PathBuf::from(path);
435	        }
436	    }
437	
438	    PathBuf::from("mutants.out")
439	}
440	
441	fn mutants_report_dir(extra: &[String]) -> PathBuf {
442	    let output_dir = mutants_output_dir(extra);
443	    if output_dir.file_name().and_then(|name| name.to_str()) == Some("mutants.out") {
444	        output_dir
445	    } else {
446	        output_dir.join("mutants.out")
447	    }
448	}
449	
450	fn mutants_generates_report(extra: &[String]) -> bool {
451	    !extra.iter().any(|arg| arg == "--list")
452	}
453	
454	fn count_non_empty_lines(path: &Path) -> usize {
455	    std::fs::read_to_string(path).ok().map_or(0, |content| {
456	        content
457	            .lines()
458	            .filter(|line| !line.trim().is_empty())
459	            .count()
460	    })
461	}
462	
463	fn collect_mutants_report_summary(report_dir: &Path) -> MutantsReportSummary {
464	    MutantsReportSummary {
465	        caught: count_non_empty_lines(&report_dir.join("caught.txt")),
466	        missed: count_non_empty_lines(&report_dir.join("missed.txt")),
467	        timeout: count_non_empty_lines(&report_dir.join("timeout.txt")),
468	        unviable: count_non_empty_lines(&report_dir.join("unviable.txt")),
469	    }
470	}
471	
472	fn print_mutants_report_overview(report_dir: &Path, summary: &MutantsReportSummary) {
473	    eprintln!("\nFull Report: {}/", report_dir.display());
474	    eprintln!("  - missed: {}", summary.missed);
475	    eprintln!("  - caught: {}", summary.caught);
476	    eprintln!("  - timeout: {}", summary.timeout);
477	    eprintln!("  - unviable: {}", summary.unviable);
478	}
479	
480	fn cargo_mutants_runs_in_place(extra: &[String]) -> bool {
481	    extra
482	        .iter()
483	        .any(|arg| arg == "--in-place" || arg.starts_with("--in-place="))
484	}
485	
486	fn build_mutants_command_args(package: &str, jobs: usize, extra: Vec<String>) -> Vec<String> {
487	    let in_place = cargo_mutants_runs_in_place(&extra);
488	    let mut cmd_args = vec!["mutants".to_string(), "-p".to_string(), package.to_string()];
489	    if !in_place {
490	        cmd_args.push("-j".to_string());
491	        cmd_args.push(jobs.to_string());
492	    }
493	    cmd_args.extend(extra);
494	    cmd_args
495	}
496	
497	fn parse_jobs(raw: &str) -> Result<usize, String> {
498	    let jobs = raw
499	        .parse::<usize>()
500	        .map_err(|_| "jobs 必须是正整数".to_string())?;
501	
502	    if jobs == 0 {
503	        return Err("jobs 必须大于 0".to_string());
504	    }
505	
506	    Ok(jobs)
507	}
508	
509	fn run_mutants(sh: &Shell, args: MutantsArgs) -> anyhow::Result<()> {
510	    ensure_cargo_mutants_available(sh)?;
511	
512	    let package = args.package.cargo_package_name();
513	    let report_dir = mutants_report_dir(&args.extra);
514	    let expects_report = mutants_generates_report(&args.extra);
515	    let cmd_args = build_mutants_command_args(package, args.jobs, args.extra);
516	
517	    let str_args: Vec<&str> = cmd_args.iter().map(String::as_str).collect();
518	    let status = run_status(&format!("cargo mutants -p {package}"), "cargo", &str_args)?;
519	
520	    let summary = expects_report.then(|| collect_mutants_report_summary(&report_dir));
521	    if let Some(summary) = &summary {
522	        print_mutants_report_overview(&report_dir, summary);
523	    }
524	
525	    if status.success() {
526	        return Ok(());
527	    }
528	
529	    if let Some(summary) = &summary
530	        && summary.missed > 0
531	    {
532	        anyhow::bail!(
533	            "mutation testing found {} missed mutants; see {}/",
534	            summary.missed,
535	            report_dir.display()
536	        );
537	    }
538	
539	    let code = status
540	        .code()
541	        .map_or_else(|| "unknown".to_string(), |value| value.to_string());
542	    anyhow::bail!(
543	        "cargo-mutants exited with code {code}; see {}/",
544	        report_dir.display()
545	    );
546	}
547	
548	//=============================================================================
549	// script-check 命令实现
550	//=============================================================================
551	
552	/// 脚本检查配置
553	struct ScriptCheckConfig {
554	    /// 脚本目录（相对于 workspace root）
555	    scripts_dir: PathBuf,
556	    /// 资源根目录（相对于 workspace root）
557	    assets_root: PathBuf,
558	}
559	
560	/// 脚本检查结果
561	struct ScriptCheckResult {
562	    /// 检查的脚本数量
563	    scripts_checked: usize,
564	    /// 解析错误数量
565	    parse_errors: usize,
566	    /// 诊断结果
567	    diagnostics: DiagnosticResult,
568	    /// 缺失的资源文件
569	    missing_resources: Vec<MissingResource>,
570	}
571	
572	/// 缺失的资源信息
573	struct MissingResource {
574	    script_id: String,
575	    resource_type: String,
576	    path: String,
577	}
578	
579	/// 执行脚本检查
580	fn script_check(args: ScriptCheckArgs) -> anyhow::Result<()> {
581	    let config = ScriptCheckConfig {
582	        scripts_dir: args.scripts_dir,
583	        assets_root: args.assets_root,
584	    };
585	
586	    // 确定要检查的文件
587	    let files = if let Some(p) = args.path {
588	        if p.is_file() {
589	            if is_script_file(&p) {
590	                vec![p]
591	            } else {
592	                anyhow::bail!("仅支持 .rks 脚本文件: {}", p.display());
593	            }
594	        } else if p.is_dir() {
595	            collect_script_files(&p)?
596	        } else {
597	            anyhow::bail!("路径不存在: {}", p.display());
598	        }
599	    } else {
600	        if !config.scripts_dir.exists() {
601	            anyhow::bail!(
602	                "默认脚本目录不存在: {}\n请在 workspace 根目录运行，或指定脚本路径",
603	                config.scripts_dir.display()
604	            );
605	        }
606	        collect_script_files(&config.scripts_dir)?
607	    };
608	
609	    if files.is_empty() {
610	        eprintln!("未找到脚本文件（.rks）");
611	        return Ok(());
612	    }
613	
614	    eprintln!("==> 检查 {} 个脚本文件...\n", files.len());
615	
616	    let mut result = ScriptCheckResult {
617	        scripts_checked: 0,
618	        parse_errors: 0,
619	        diagnostics: DiagnosticResult::new(),
620	        missing_resources: Vec::new(),
621	    };
622	
623	    // 检查每个脚本
624	    for file in &files {
625	        check_script_file(file, &config, &mut result);
626	    }
627	
628	    // 输出结果
629	    print_check_result(&result);
630	
631	    // 如果有错误则返回失败
632	    if result.parse_errors > 0 || result.diagnostics.has_errors() {
633	        anyhow::bail!("脚本检查发现错误");
634	    }
635	
636	    Ok(())
637	}
638	
639	/// 收集目录下的所有脚本文件
640	fn collect_script_files(dir: &Path) -> anyhow::Result<Vec<PathBuf>> {
641	    let mut files = Vec::new();
642	    for entry in WalkDir::new(dir).follow_links(false) {
643	        let entry = entry?;
644	        if entry.file_type().is_file() && is_script_file(entry.path()) {
645	            files.push(entry.path().to_path_buf());
646	        }
647	    }
648	    files.sort();
649	    Ok(files)
650	}
651	
652	/// 检查单个脚本文件
653	fn check_script_file(file: &Path, config: &ScriptCheckConfig, result: &mut ScriptCheckResult) {
654	    let script_id = file.display().to_string();
655	    result.scripts_checked += 1;
656	
657	    // 读取文件
658	    let content = match std::fs::read_to_string(file) {
659	        Ok(c) => c,
660	        Err(e) => {
661	            eprintln!("[ERROR] {script_id}: 无法读取文件 - {e}");
662	            result.parse_errors += 1;
663	            return;
664	        }
665	    };
666	
667	    // 计算 base_path（脚本所在目录，相对于 assets_root）
668	    let base_path = compute_base_path(file, &config.assets_root);
669	
670	    // 解析脚本
671	    let mut parser = ScriptParser::new();
672	    let script = match parser.parse_with_base_path(&script_id, &content, &base_path) {
673	        Ok(s) => s,
674	        Err(e) => {
675	            eprintln!("[ERROR] {script_id}: {e}");
676	            result.parse_errors += 1;
677	            return;
678	        }
679	    };
680	
681	    // 输出解析警告
682	    for warning in parser.warnings() {
683	        eprintln!("[WARN] {script_id}: {warning}");
684	    }
685	
686	    // 运行诊断分析
687	    let diag = analyze_script(&script);
688	    result.diagnostics.merge(diag);
689	
690	    // 检查资源引用
691	    let refs = extract_resource_references(&script);
692	    for r in refs {
693	        let resource_path = config.assets_root.join(&r.resolved_path);
694	        if !resource_path.exists() {
695	            result.missing_resources.push(MissingResource {
696	                script_id: script_id.clone(),
697	                resource_type: format!("{}", r.resource_type),
698	                path: r.resolved_path,
699	            });
700	        }
701	    }
702	}
703	
704	/// 计算脚本的 `base_path（相对于` `assets_root`）
705	fn compute_base_path(file: &Path, assets_root: &Path) -> String {
706	    // 尝试获取相对路径
707	    if let Ok(relative) = file.strip_prefix(assets_root)
708	        && let Some(parent) = relative.parent()
709	    {
710	        return normalize_path(parent.to_string_lossy().as_ref());
711	    }
712	
713	    // 如果无法获取相对路径，使用文件所在目录
714	    file.parent()
715	        .map(|p| normalize_path(p.to_string_lossy().as_ref()))
716	        .unwrap_or_default()
717	}
718	
719	fn normalize_path(path: &str) -> String {
720	    path.replace('\\', "/").trim_start_matches('/').to_string()
721	}
722	
723	fn is_script_file(path: &Path) -> bool {
724	    path.extension()
725	        .and_then(|ext| ext.to_str())
726	        .is_some_and(|ext| ext.eq_ignore_ascii_case("rks"))
727	}
728	
729	/// 输出检查结果
730	fn print_check_result(result: &ScriptCheckResult) {
731	    eprintln!("─────────────────────────────────────────────────────");
732	    eprintln!("检查完成: {} 个脚本", result.scripts_checked);
733	    eprintln!();
734	
735	    // 输出诊断
736	    for diag in &result.diagnostics.diagnostics {
737	        eprintln!("{diag}");
738	    }
739	
740	    // 输出缺失资源
741	    for mr in &result.missing_resources {
742	        eprintln!(
743	            "[WARN] {}: 资源不存在 [{}] {}",
744	            mr.script_id, mr.resource_type, mr.path
745	        );
746	    }
747	
748	    // 汇总
749	    let error_count = result.parse_errors + result.diagnostics.error_count();
750	    let warn_count = result.diagnostics.warn_count() + result.missing_resources.len();
751	
752	    eprintln!();
753	    if error_count > 0 {
754	        eprintln!("❌ {error_count} 个错误, {warn_count} 个警告");
755	    } else if warn_count > 0 {
756	        eprintln!("⚠️  0 个错误, {warn_count} 个警告");
757	    } else {
758	        eprintln!("✅ 检查通过，无错误");
759	    }
760	}
761

