7	//!
8	//! 复用自 `host/src/ui/screen_defs/mod.rs`，移除 egui 依赖。
9	
10	use std::fmt;
11	
12	use serde::{
13	    Deserialize,
14	    de::{self, MapAccess, Visitor},
15	};
16	use vn_runtime::state::VarValue;
17	
18	use crate::{
19	    resources::{LogicalPath, ResourceManager},
20	    state::PersistentStore,
21	};
22	
23	// ─── ConditionDef ─────────────────────────────────────────────────────────────
24	
25	/// 可见性/背景选择条件
26	///
27	/// 极简单变量布尔判断，覆盖当前所有已知条件需求。
28	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
29	pub enum ConditionDef {
30	    /// 始终为 true
31	    Always,
32	    /// 存在可继续的存档
33	    HasContinue,
34	    /// 持久化变量为 truthy
35	    PersistentVar(String),
36	    /// 持久化变量不为 truthy
37	    NotPersistentVar(String),
38	}
39	
40	impl<'de> Deserialize<'de> for ConditionDef {
41	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
42	    where
43	        D: de::Deserializer<'de>,
44	    {
45	        let s = String::deserialize(deserializer)?;
46	        Ok(parse_condition(&s))
47	    }
48	}
49	
50	#[expect(
51	    clippy::string_slice,
52	    reason = "slicing past known ASCII prefix lengths, always char boundaries"
53	)]
54	fn parse_condition(s: &str) -> ConditionDef {
55	    match s {
56	        "true" | "" => ConditionDef::Always,
57	        "$has_continue" => ConditionDef::HasContinue,
58	        _ if s.starts_with("!$persistent.") => {
59	            ConditionDef::NotPersistentVar(s["!$persistent.".len()..].to_string())
60	        }
61	        _ if s.starts_with("$persistent.") => {
62	            ConditionDef::PersistentVar(s["$persistent.".len()..].to_string())
63	        }
64	        other => {
65	            tracing::warn!(
66	                condition = other,
67	                "Unknown condition syntax, treating as Always"
68	            );
69	            ConditionDef::Always
70	        }
71	    }
72	}
73	
74	// ─── Condition Evaluation ─────────────────────────────────────────────────────
75	
76	/// 条件求值上下文（在渲染循环开始时一次性构造）
77	pub struct ConditionContext<'a> {
78	    pub has_continue: bool,
79	    pub persistent: &'a PersistentStore,
80	}
81	
82	impl ConditionDef {
83	    /// 在给定上下文中求值
84	    pub fn evaluate(&self, ctx: &ConditionContext<'_>) -> bool {
85	        match self {
86	            ConditionDef::Always => true,
87	            ConditionDef::HasContinue => ctx.has_continue,
88	            ConditionDef::PersistentVar(key) => is_var_truthy(ctx.persistent, key),
89	            ConditionDef::NotPersistentVar(key) => !is_var_truthy(ctx.persistent, key),
90	        }
91	    }
92	}
93	
94	fn is_var_truthy(store: &PersistentStore, key: &str) -> bool {
95	    store
96	        .variables
97	        .get(key)
98	        .is_some_and(|v| matches!(v, VarValue::Bool(true)))
99	}
100	
101	// ─── ActionDef ────────────────────────────────────────────────────────────────
102	
103	/// 声明式动作定义
104	///
105	/// 编译期已知的动作词汇表，由 binary crate 映射为应用层操作。
106	#[derive(Debug, Clone, PartialEq, Eq)]
107	pub enum ActionDef {
108	    StartGame,
109	    ContinueGame,
110	    OpenLoad,
111	    OpenSave,
112	    NavigateSettings,
113	    NavigateHistory,
114	    /// 替换当前模式为 Settings（不压栈，用于游戏菜单同级切换）
115	    ReplaceSettings,
116	    /// 替换当前模式为 History（不压栈，用于游戏菜单同级切换）
117	    ReplaceHistory,
118	    QuickSave,
119	    QuickLoad,
120	    ToggleSkip,
121	    ToggleAuto,
122	    GoBack,
123	    ReturnToTitle,
124	    ReturnToGame,
125	    Exit,
126	    /// 从指定标签开始新游戏（泛化 `StartWinter`）
127	    StartAtLabel(String),
128	}
129	
130	impl<'de> Deserialize<'de> for ActionDef {
131	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
132	    where
133	        D: de::Deserializer<'de>,
134	    {
135	        struct ActionDefVisitor;
136	
137	        impl<'de> Visitor<'de> for ActionDefVisitor {
138	            type Value = ActionDef;
139	
140	            fn expecting(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
141	                f.write_str("a string action ID or an object like {\"start_at_label\": \"X\"}")
142	            }
143	
144	            fn visit_str<E: de::Error>(self, v: &str) -> Result<ActionDef, E> {
145	                match v {
146	                    "start_game" => Ok(ActionDef::StartGame),
147	                    "continue_game" => Ok(ActionDef::ContinueGame),
148	                    "open_load" => Ok(ActionDef::OpenLoad),
149	                    "open_save" => Ok(ActionDef::OpenSave),
150	                    "navigate_settings" => Ok(ActionDef::NavigateSettings),
151	                    "navigate_history" => Ok(ActionDef::NavigateHistory),
152	                    "replace_settings" => Ok(ActionDef::ReplaceSettings),
153	                    "replace_history" => Ok(ActionDef::ReplaceHistory),
154	                    "quick_save" => Ok(ActionDef::QuickSave),
155	                    "quick_load" => Ok(ActionDef::QuickLoad),
156	                    "toggle_skip" => Ok(ActionDef::ToggleSkip),
157	                    "toggle_auto" => Ok(ActionDef::ToggleAuto),
158	                    "go_back" => Ok(ActionDef::GoBack),
159	                    "return_to_title" => Ok(ActionDef::ReturnToTitle),
160	                    "return_to_game" => Ok(ActionDef::ReturnToGame),
161	                    "exit" => Ok(ActionDef::Exit),
162	                    other => Err(de::Error::unknown_variant(
163	                        other,
164	                        &[
165	                            "start_game",
166	                            "continue_game",
167	                            "open_load",
168	                            "open_save",
169	                            "navigate_settings",
170	                            "navigate_history",
171	                            "replace_settings",
172	                            "replace_history",
173	                            "quick_save",
174	                            "quick_load",
175	                            "toggle_skip",
176	                            "toggle_auto",
177	                            "go_back",
178	                            "return_to_title",
179	                            "return_to_game",
180	                            "exit",
181	                        ],
182	                    )),
183	                }
184	            }
185	
186	            fn visit_map<M: MapAccess<'de>>(self, mut map: M) -> Result<ActionDef, M::Error> {
187	                let mut start_at_label: Option<String> = None;
188	                while let Some(key) = map.next_key::<String>()? {
189	                    match key.as_str() {
190	                        "start_at_label" => {
191	                            start_at_label = Some(map.next_value()?);
192	                        }
193	                        other => {
194	                            return Err(de::Error::unknown_field(other, &["start_at_label"]));
195	                        }
196	                    }
197	                }
198	                start_at_label
199	                    .map(ActionDef::StartAtLabel)
200	                    .ok_or_else(|| de::Error::missing_field("start_at_label"))
201	            }
202	        }
203	
204	        deserializer.deserialize_any(ActionDefVisitor)
205	    }
206	}
