208	// ─── ButtonDef ────────────────────────────────────────────────────────────────
209	
210	/// 按钮定义
211	#[derive(Debug, Clone, Deserialize)]
212	pub struct ButtonDef {
213	    /// 按钮文案
214	    pub label: String,
215	    /// 点击动作
216	    pub action: ActionDef,
217	    /// 可见性条件（缺失视为 Always）
218	    #[serde(default)]
219	    pub visible: Option<ConditionDef>,
220	    /// 确认弹窗文案（非 None 时点击先弹确认）
221	    #[serde(default)]
222	    pub confirm: Option<String>,
223	}
