225	// ─── ConditionalAsset ─────────────────────────────────────────────────────────
226	
227	/// 条件化资源引用（用于背景切换）
228	#[derive(Debug, Clone, Deserialize)]
229	pub struct ConditionalAsset {
230	    /// 条件（缺失视为 Always，即兜底资源）
231	    #[serde(default)]
232	    pub when: Option<ConditionDef>,
233	    /// 资源 key
234	    pub asset: String,
235	}
236	
237	impl ConditionalAsset {
238	    /// 从条件资源列表中选出第一个满足条件的资源 key
239	    pub fn resolve<'a>(
240	        assets: &'a [ConditionalAsset],
241	        ctx: &ConditionContext<'_>,
242	    ) -> Option<&'a str> {
243	        assets.iter().find_map(|ca| {
244	            let passes = ca.when.as_ref().is_none_or(|cond| cond.evaluate(ctx));
245	            passes.then_some(ca.asset.as_str())
246	        })
247	    }
248	}
