266	}
267	
268	/// 游戏菜单定义（左导航 + 右内容）
269	#[derive(Debug, Clone, Deserialize)]
270	#[serde(deny_unknown_fields)]
271	pub struct GameMenuDef {
272	    pub background: Vec<ConditionalAsset>,
273	    pub overlay: Option<String>,
274	    pub nav_buttons: Vec<ButtonDef>,
275	    pub return_button: ButtonDef,
276	}
