278	/// 所有界面的行为定义
279	#[derive(Debug, Clone, Deserialize)]
280	#[serde(deny_unknown_fields)]
281	pub struct ScreenDefinitions {
282	    pub title: TitleScreenDef,
283	    pub ingame_menu: ButtonListDef,
284	    pub quick_menu: ButtonListDef,
285	    pub game_menu: GameMenuDef,
286	}
