288	/// 界面行为配置加载错误
289	#[derive(Debug)]
290	pub enum ScreenDefsError {
291	    /// 配置文件缺失或读取失败
292	    NotFound(String),
293	    /// JSON 解析失败
294	    ParseFailed(String),
295	}
296	
297	impl std::fmt::Display for ScreenDefsError {
298	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
299	        match self {
300	            ScreenDefsError::NotFound(msg) => write!(f, "界面配置加载失败: {msg}"),
301	            ScreenDefsError::ParseFailed(msg) => write!(f, "界面配置解析失败: {msg}"),
302	        }
303	    }
304	}
305	
306	impl std::error::Error for ScreenDefsError {}
