308	impl ScreenDefinitions {
309	    /// 测试用默认值（不依赖资源文件）
310	    #[cfg(test)]
311	    pub fn default_for_tests() -> Self {
312	        Self {
313	            title: TitleScreenDef {
314	                background: vec![ConditionalAsset {
