351	
352	    /// 从 `ResourceManager` 加载界面行为配置。
353	    ///
354	    /// 配置文件 `ui/screens.json` 必须存在且字段完整，否则返回错误。
355	    pub fn load(resource_manager: &ResourceManager) -> Result<Self, ScreenDefsError> {
356	        let path = LogicalPath::new("ui/screens.json");
357	        let content = resource_manager
358	            .read_text_optional(&path)
