                        }
                        other => {
                            return Err(de::Error::unknown_field(other, &["start_at_label"]));
                        }
                    }
                }
                start_at_label
                    .map(ActionDef::StartAtLabel)
                    .ok_or_else(|| de::Error::missing_field("start_at_label"))
            }
        }

        deserializer.deserialize_any(ActionDefVisitor)
    }
}

