1	//! 音频状态追踪器（headless）
2	//!
3	//! `AudioManager` 只追踪音频逻辑状态（当前 BGM、音量、duck），
4	//! 不做任何 I/O。实际播放由前端负责。
5	
6	use tracing::debug;
7	
8	use crate::{
9	    render_state::{AudioRenderState, BgmState, BgmTransition, SfxRequest},
10	    resources::normalize_logical_path,
11	};
12	
13	/// 音频管理器（headless 状态追踪）
14	pub struct AudioManager {
15	    current_bgm_path: Option<String>,
16	    bgm_looping: bool,
17	    bgm_volume: f32,
18	    sfx_volume: f32,
19	    muted: bool,
20	    duck_multiplier: f32,
21	    duck_target: f32,
22	    sfx_queue: Vec<SfxRequest>,
23	    pending_transition: Option<f32>,
24	}
25	
26	impl Default for AudioManager {
27	    fn default() -> Self {
28	        Self::new()
29	    }
30	}
31	
32	impl AudioManager {
33	    const DUCK_VOLUME_RATIO: f32 = 0.3;
34	    const DUCK_FADE_SPEED: f32 = 3.0;
35	    const CROSSFADE_DURATION: f32 = 1.0;
36	    const FADE_IN_DURATION: f32 = 0.5;
37	
38	    pub fn new() -> Self {
39	        Self {
40	            current_bgm_path: None,
41	            bgm_looping: true,
42	            bgm_volume: 1.0,
43	            sfx_volume: 1.0,
44	            muted: false,
45	            duck_multiplier: 1.0,
46	            duck_target: 1.0,
47	            sfx_queue: Vec::new(),
48	            pending_transition: None,
49	        }
50	    }
51	
52	    pub fn set_bgm_volume(&mut self, volume: f32) {
53	        self.bgm_volume = volume.clamp(0.0, 1.0);
54	    }
55	
56	    pub fn set_sfx_volume(&mut self, volume: f32) {
57	        self.sfx_volume = volume.clamp(0.0, 1.0);
58	    }
59	
60	    pub fn current_bgm_path(&self) -> Option<&str> {
61	        self.current_bgm_path.as_deref()
62	    }
63	
64	    pub fn play_bgm(&mut self, path: &str, looping: bool, _fade_in: Option<f32>) {
65	        let logical_path = normalize_logical_path(path);
66	        let is_same = self
67	            .current_bgm_path
68	            .as_ref()
69	            .is_some_and(|p| *p == logical_path);
70	        if !is_same {
71	            let duration = if self.current_bgm_path.is_some() {
72	                Self::CROSSFADE_DURATION
73	            } else {
74	                Self::FADE_IN_DURATION
75	            };
76	            self.pending_transition = Some(duration);
77	        }
78	        self.current_bgm_path = Some(logical_path.clone());
79	        self.bgm_looping = looping;
80	        debug!(path = %logical_path, looping, "BGM state: play");
81	    }
82	
83	    pub fn stop_bgm(&mut self, fade_out: Option<f32>) {
84	        if self.current_bgm_path.is_none() {
85	            return;
86	        }
87	        if let Some(duration) = fade_out {
88	            self.pending_transition = Some(duration);
89	        }
90	        self.current_bgm_path = None;
91	        debug!("BGM state: stop");
92	    }
93	
94	    pub fn play_sfx(&mut self, path: &str) {
95	        let logical_path = normalize_logical_path(path);
96	        let volume = if self.muted { 0.0 } else { self.sfx_volume };
97	        self.sfx_queue.push(SfxRequest {
98	            path: logical_path.clone(),
99	            volume,
100	        });
101	        debug!(path = %logical_path, "SFX state: queued");
102	    }
103	
104	    pub fn duck(&mut self) {
105	        self.duck_target = Self::DUCK_VOLUME_RATIO;
106	        debug!("BGM duck -> {:.0}%", self.duck_target * 100.0);
107	    }
108	
109	    pub fn unduck(&mut self) {
110	        self.duck_target = 1.0;
111	        debug!("BGM unduck -> 100%");
112	    }
113	
114	    pub fn update(&mut self, dt: f32) {
115	        let diff = self.duck_target - self.duck_multiplier;
116	        if diff.abs() > 0.001 {
117	            let step = Self::DUCK_FADE_SPEED * dt;
118	            if diff > 0.0 {
119	                self.duck_multiplier = (self.duck_multiplier + step).min(self.duck_target);
120	            } else {
121	                self.duck_multiplier = (self.duck_multiplier - step).max(self.duck_target);
122	            }
123	        }
124	    }
125	
126	    pub fn drain_audio_state(&mut self) -> AudioRenderState {
127	        let bgm = self.current_bgm_path.as_ref().map(|path| {
128	            let volume = if self.muted {
129	                0.0
130	            } else {
131	                self.bgm_volume * self.duck_multiplier
132	            };
133	            BgmState {
134	                path: path.clone(),
135	                looping: self.bgm_looping,
136	                volume,
137	            }
138	        });
139	        let sfx_queue = std::mem::take(&mut self.sfx_queue);
140	        let bgm_transition = self
141	            .pending_transition
142	            .take()
143	            .map(|duration| BgmTransition { duration });
144	        AudioRenderState {
145	            bgm,
146	            sfx_queue,
147	            bgm_transition,
148	        }
149	    }
150	}
