152	#[cfg(test)]
153	mod tests {
154	    use super::*;
155	
156	    fn new_manager() -> AudioManager {
157	        AudioManager::new()
158	    }
159	
160	    #[test]
161	    fn play_bgm_same_path_no_transition() {
162	        let mut am = new_manager();
163	        am.play_bgm("bgm/track1.ogg", true, None);
164	        am.drain_audio_state();
165	        am.play_bgm("bgm/track1.ogg", true, None);
166	        let state = am.drain_audio_state();
167	        assert!(state.bgm_transition.is_none());
168	    }
169	
