171	    fn play_bgm_first_time_uses_fade_in() {
172	        let mut am = new_manager();
173	        am.play_bgm("bgm/track1.ogg", true, None);
174	        let state = am.drain_audio_state();
175	        let t = state.bgm_transition.expect("should have transition");
176	        assert_eq!(t.duration, AudioManager::FADE_IN_DURATION);
177	    }
178	
179	    #[test]
180	    fn play_bgm_switch_uses_crossfade() {
181	        let mut am = new_manager();
182	        am.play_bgm("bgm/track1.ogg", true, None);
183	        am.drain_audio_state();
